import assert from 'node:assert/strict';
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { chromium } from 'playwright';
import { createStaticServer } from '../../GameStarter/web-demo/serve.mjs';

const build = resolve(process.argv[2] ?? 'GameStarter/web-demo/.build');
const output = resolve(process.argv[3] ?? 'outputs/thought-entry-20261023');
// Generated by thought-entry.test.mjs through actual session actions.
const beforeEntry = readFileSync(resolve(output, 'before-entry.json'), 'utf8');
const key = 'wuzhang-chapter-session-v1';
mkdirSync(output, { recursive: true });
const server = createStaticServer({ root: build });
await new Promise(ok => server.listen(0, '127.0.0.1', ok));
const base = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch({ headless: true, channel: process.env.SMOKE_BROWSER_CHANNEL ?? 'chrome' });
const report = { passed: false, checks: [], screenshots: [], errors: [] };
try {
  for (const [width, height, reduced] of [[1366, 768, false], [1280, 720, true]]) {
    const context = await browser.newContext({ viewport: { width, height }, reducedMotion: reduced ? 'reduce' : 'no-preference', serviceWorkers: 'block' });
    await context.route('**/api/**', route => route.fulfill({ status: 503, contentType: 'application/json', body: '{"error":"isolated UI test"}' }));
    const page = await context.newPage();
    page.on('pageerror', error => report.errors.push(error.message));
    await page.goto(base);
    await page.evaluate(({ key, beforeEntry, reduced }) => {
      localStorage.setItem(key, beforeEntry);
      localStorage.setItem('wuzhang-reduced-motion', reduced ? '1' : '0');
    }, { key, beforeEntry, reduced });
    await page.reload();
    await page.locator('[data-action=continue]').click();
    await page.waitForFunction(() => document.querySelector('#spoken-line')?.textContent === '上一回，魏延说敌军还在问：丞相为何不出、如今谁在发令。');
    const background = await page.locator('.scene-image').getAttribute('style');
    // Repeated Enter from the last line cannot also activate the newly focused option.
    await page.locator('.dialogue-advance').focus();
    await page.keyboard.down('Enter');
    await page.keyboard.down('Enter');
    await page.keyboard.up('Enter');
    await page.locator('[data-phase=thought-prompt]').waitFor();
    assert.equal(await page.locator('.scene-image').getAttribute('style'), background);
    const option = page.locator('[data-action=begin-thinking]');
    assert.equal(await option.innerText(), '让我想一想\n›');
    assert.equal(await page.locator('[data-action=notes]').isDisabled(), true);
    assert.equal(await page.locator('.dialogue-key-hint').count(), 0);
    await page.mouse.click(20, 320);
    await page.evaluate(() => document.activeElement?.blur());
    await page.keyboard.press('Space');
    await page.waitForTimeout(1800);
    assert.equal(await page.locator('[data-phase=thought-prompt]').count(), 1);
    await option.dispatchEvent('click', { detail: 2 });
    assert.equal(await page.locator('[data-phase=thought-prompt]').count(), 1);
    const box = await page.locator('.thought-entry-choice').boundingBox();
    assert.ok(Math.abs(box.width - width * .7) < 2);
    assert.ok(Math.abs(box.x - (width - box.width) / 2) < 2);
    await page.screenshot({ path: resolve(output, `${width}x${height}-choice.png`) });
    report.screenshots.push(`${width}x${height}-choice.png`);
    // Prompt save/load remains waiting; opening and reopening preserve the canvas.
    await page.reload(); await page.locator('[data-action=continue]').click();
    await page.locator('[data-phase=thought-prompt]').waitFor();
    const save = await page.evaluate(key => JSON.parse(localStorage.getItem(key)), key);
    assert.ok(save.story.completed.includes('D26'));
    assert.ok(!save.panelOpened.includes('P1'));
    if (reduced) await page.locator('[data-action=begin-thinking]').press('Space');
    else await page.locator('[data-action=begin-thinking]').click();
    await page.locator('[data-phase=thoughts]').waitFor();
    const animation = await page.locator('.workspace-screen').evaluate(node => ({ name: getComputedStyle(node).animationName, mark: node.classList.contains('is-unfolding') }));
    assert.equal(animation.mark, !reduced);
    if (!reduced) assert.equal(animation.name, 'thought-entry-wash');
    await page.waitForTimeout(850);
    await page.screenshot({ path: resolve(output, `${width}x${height}-opened.png`) });
    report.screenshots.push(`${width}x${height}-opened.png`);
    await page.reload(); await page.locator('[data-action=continue]').click();
    await page.locator('[data-phase=thoughts]').waitFor();
    assert.equal(await page.locator('.is-unfolding').count(), 0);
    await page.locator('[data-action=notes]').click();
    await page.locator('[data-phase=explore]').waitFor();
    await page.locator('.game-hud [data-action=notes]').click();
    await page.locator('[data-phase=thoughts]').waitFor();
    assert.equal(await page.locator('.is-unfolding').count(), 0);
    report.checks.push({ width, height, reduced, waiting: true, noAccidentalSkip: true, savedPrompt: true, explicitOpening: animation, noReplayOnLoadOrReopen: true });
    await context.close();
  }
  assert.deepEqual(report.errors, []); report.passed = true;
} finally {
  writeFileSync(resolve(output, 'browser-checks.json'), JSON.stringify(report, null, 2));
  await browser.close(); await new Promise(ok => server.close(ok));
}
console.log(JSON.stringify(report, null, 2));
